L000088	\title{Universal two-excitation scattering in two-dimensional subwavelength atomic arrays
L000089	}
L000090	
L000091	\author{Yidan Wang}
L000092	\affiliation{Department of Physics, Harvard University, Cambridge, Massachusetts 02138, USA}
L000093	\author{Oriol Rubies-Bigorda}
L000094	\affiliation{Physics Department, Massachusetts Institute of Technology, Cambridge, Massachusetts 02139, USA}
L000095	\author{Valentin Walther}
L000096	 \affiliation{Department of Physics and Astronomy, Purdue University, West Lafayette, Indiana 47907, USA}
L000097	 \affiliation{Department of Chemistry, Purdue University, West Lafayette, Indiana 47907, USA}
